var generatedCatalog struct {
	sync.Once
	manifests []Manifest
	byID      map[string]Manifest
	err       error
}

func loadGeneratedCatalog() {
	generatedCatalog.err = json.Unmarshal([]byte(generatedCatalogJSON), &generatedCatalog.manifests)
	generatedCatalog.byID = make(map[string]Manifest, len(generatedCatalog.manifests))
	if generatedCatalog.err != nil {
		return
	}
	for index, manifest := range generatedCatalog.manifests {
		if err := manifest.Validate(); err != nil {
			generatedCatalog.err = err
			return
		}
		manifest = manifest.Canonical()
		generatedCatalog.manifests[index] = manifest
		generatedCatalog.byID[manifest.ID] = manifest
	}
}

// CatalogManifests returns the reviewed provider-neutral connector metadata.
func CatalogManifests() ([]Manifest, error) {
	generatedCatalog.Do(loadGeneratedCatalog)
	if generatedCatalog.err != nil {
		return nil, generatedCatalog.err
	}
	return append([]Manifest(nil), generatedCatalog.manifests...), nil
}

// CatalogManifest resolves one canonical manifest without importing providers.
func CatalogManifest(id string) (Manifest, error) {
	generatedCatalog.Do(loadGeneratedCatalog)
	if generatedCatalog.err != nil {
		return Manifest{}, generatedCatalog.err
	}
	manifest, ok := generatedCatalog.byID[id]
	if !ok {
		return Manifest{}, ErrConnectorNotFound
	}
	return manifest, nil
}
